from itertools import combinations
from fractions import Fraction as F
P={"TL":(0,0),"T":(6,0),"TR":(12,0),"L":(0,4),"C":(6,4),"R":(12,4),"BL":(0,8),"B":(6,8),"BR":(12,8)}
def onseg(p,a,b):
    (x,y),(x1,y1),(x2,y2)=p,a,b
    return (x2-x1)*(y-y1)==(y2-y1)*(x-x1) and min(x1,x2)<=x<=max(x1,x2) and min(y1,y2)<=y<=max(y1,y2)
def inter(a,b,c,d):
    (x1,y1),(x2,y2),(x3,y3),(x4,y4)=a,b,c,d
    den=(x1-x2)*(y3-y4)-(y1-y2)*(x3-x4)
    t=F((x1-x3)*(y3-y4)-(y1-y3)*(x3-x4),den)
    return (x1+t*(x2-x1),y1+t*(y2-y1))
P["P"]=inter(P["TR"],P["C"],P["T"],P["R"])
P["Q"]=inter(P["BL"],P["C"],P["L"],P["B"])
yq=P["Q"][1]
P["X"]=(6,yq)
P["S"]=inter(P["Q"],P["X"],P["R"],P["B"])
segs=[("TL","TR"),("TR","BR"),("BR","BL"),("BL","TL"),("T","L"),("L","B"),("B","R"),("R","T"),("T","B"),("C","R"),("TR","P"),("BL","Q"),("Q","S")]
pts=list(P)
def conn(a,b):
    return any(onseg(P[a],P[s],P[e]) and onseg(P[b],P[s],P[e]) for s,e in segs)
def col(a,b,c):
    (x1,y1),(x2,y2),(x3,y3)=P[a],P[b],P[c]
    return (x2-x1)*(y3-y1)==(y2-y1)*(x3-x1)
n=sum(1 for a,b,c in combinations(pts,3) if not col(a,b,c) and conn(a,b) and conn(b,c) and conn(a,c))
opts={"A":13,"B":14,"C":15,"D":16}
assert [k for k,v in opts.items() if v==n]==["C"], n

